// Map roles to template IDs - REMOVED um_employee
const templateMap = {
  'um_account-manager': '188622000000348111',      // Account Manager template
  'um_business-developer': '188622000000357141',   // Business Developer template 
  'um_advisor': '188622000000XXXXXX',              // ADD ADVISOR TEMPLATE ID
  'customer': '188622000000366147',                // Customer template
};

const contractNames = {
  'um_account-manager': 'Account Manager Contract',
  'um_business-developer': 'Business Developer Contract',
  'um_advisor': 'Advisor Contract',
  'customer': 'Customer Agreement'
};

// Get user roles from webhook data
const userRoles = $input.first().json.body.roles || [];

// Debug: Log what roles we received
console.log('Received roles:', userRoles);

// Determine which role matches (priority order) - REMOVED um_employee
let matchedRole = null;
const contractRoles = ['um_account-manager', 'um_business-developer', 'um_advisor', 'customer'];

for (const role of contractRoles) {
  if (userRoles.includes(role)) {
    matchedRole = role;
    console.log('Matched role:', matchedRole);
    break;
  }
}

// If no contract role found, stop workflow
if (!matchedRole) {
  console.log('No contract role found for user');
  return null;
}

// Verify template ID exists and is not placeholder
if (!templateMap[matchedRole] || templateMap[matchedRole].includes('XXXXXX')) {
  console.error('Invalid or missing template ID for role:', matchedRole);
  return null;
}

// Get first and last name from user_meta (it's an array)
const firstName = $input.first().json.body.user_meta.first_name?.[0] || '';
const lastName = $input.first().json.body.user_meta.last_name?.[0] || '';

// Return enriched data
return {
  json: {
    user_id: $input.first().json.body.data.ID,
    name: $input.first().json.body.data.display_name,
    email: $input.first().json.body.data.user_email,
    first_name: firstName,
    last_name: lastName,
    wordpress_url: 'https://gofunditnow.com',
    user_role: matchedRole,
    template_id: templateMap[matchedRole],
    contract_name: contractNames[matchedRole]
  }
};

